import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Public routing","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"Public routing","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/public-routing.md","filePath":"guide/cms/public-routing.md","lastUpdated":1784841066000}'),i={name:"guide/cms/public-routing.md"},s=a(`<h1 id="public-routing" tabindex="-1">Public routing <a class="header-anchor" href="#public-routing" aria-label="Permalink to &quot;Public routing&quot;">​</a></h1><p>How public HTTP routes are registered so CMS pages, system endpoints, and host routes coexist.</p><h2 id="registration-order" tabindex="-1">Registration order <a class="header-anchor" href="#registration-order" aria-label="Permalink to &quot;Registration order&quot;">​</a></h2><p>Laravel uses <strong>first match wins</strong>. Modularous registers in this order:</p><ol><li><strong>Built-in system routes</strong> (<code>CmsPublicSystemRoutes</code>) — boot — <code>/robots.txt</code>, <code>/sitemap.xml</code>, <code>/sitemap.xsl</code>, signed preview, public stylesheets</li><li><strong>Host app</strong> — <code>routes/web.php</code> (framework <code>booted</code>)</li><li><strong>CMS catch-all</strong> — <code>GET {path}</code> → <code>CmsPublicFrontController</code> (later <code>booted</code>)</li></ol><p>A host route such as <code>/test</code> in <code>routes/web.php</code> therefore beats the CMS catch-all. No package change required.</p><h2 id="where-to-define-routes" tabindex="-1">Where to define routes <a class="header-anchor" href="#where-to-define-routes" aria-label="Permalink to &quot;Where to define routes&quot;">​</a></h2><table><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>CMS product endpoints</td><td><code>modules/Cms/Routing/CmsPublicSystemRoutes.php</code></td></tr><tr><td>App-specific paths</td><td>Host <code>routes/web.php</code></td></tr><tr><td>Third-party paths still eaten by <code>{path}</code></td><td>Config exclude (below)</td></tr></tbody></table><p>Enabled system prefixes are removed from the catch-all <code>{path}</code> regex via <code>CmsPublicSystemRoutes::reservedPathPrefixes()</code> (also used by visitor-redirect / URL-stale skip logic).</p><h2 id="catch-all-exclude-config" tabindex="-1">Catch-all exclude config <a class="header-anchor" href="#catch-all-exclude-config" aria-label="Permalink to &quot;Catch-all exclude config&quot;">​</a></h2><p><strong>Usually not needed</strong> for <code>routes/web.php</code> — order already wins.</p><p>Use <code>modularous.cms_routing.public_front_catch_all_exclude_path_prefixes</code> when:</p><ul><li>Another package registers <strong>after</strong> the catch-all (or on a domain that never matches), so <code>{path}</code> still wins</li><li>You want belt-and-suspenders so CMS never treats that path as a page</li><li>Stale/redirect middleware should ignore the path (same reserved list)</li></ul><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;public_front_catch_all_exclude_path_prefixes&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;health&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;horizon&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>Slash-trimmed; <code>health</code> blocks <code>health</code> and <code>health/...</code>.</p><h2 id="domain-binding" tabindex="-1">Domain binding <a class="header-anchor" href="#domain-binding" aria-label="Permalink to &quot;Domain binding&quot;">​</a></h2><p>Public CMS routes use <code>CmsFrontRouteRegistrar::resolvePublicFrontRouteDomain()</code> (host from <code>APP_URL</code> or <code>public_front_route_domain</code>). System routes bind the same way when registered through the catalog.</p><h2 id="related-config" tabindex="-1">Related config <a class="header-anchor" href="#related-config" aria-label="Permalink to &quot;Related config&quot;">​</a></h2><p><code>modularous.cms_routing.*</code> — auto-register, universal front, localization mode, signed preview, visitor redirects. See <a href="./configuration">Configuration</a>.</p>`,19),r=[s];function d(l,n,c,h,p,u){return o(),t("div",null,r)}const m=e(i,[["render",d]]);export{b as __pageData,m as default};
